# Define canonical nested pattern based on UL observations
def P(h,w):
    a=[[0]*w for _ in range(h)]
    off=0 if w%2==0 else 1
    for k,c in enumerate(range(off,w,2)):
        s=k*(k-1) if w%2==0 else k*(k+1)//2
        for r in range(min(h,s),h): a[r][c]=1
        if k>0 and s<h:
            for j in range(c,w): a[s][j]=1
    return a
def rot(a): return [list(row) for row in zip(*a[::-1])]
def transforms(a):
    result=[]; b=a
    for k in range(4):
        for x in (b,[row[::-1] for row in b]): result.append(x)
        b=rot(b)
    return result
# actual masks from demos
for name, grid, rs,cs,h,w in [('Aul',d20,0,0,5,7),('Aur',d20,0,8,5,12),('All',d20,6,0,14,7),('Alr',d20,6,8,14,12),('Bul',d10,0,0,4,6),('Bur',d10,0,7,4,3),('Bll',d10,5,0,5,6),('Blr',d10,5,7,5,3)]:
    actual=[[int(grid[rs+r][cs+c]==4) for c in range(w)] for r in range(h)]
    p=P(h,w)
    scores=[]
    for i,t in enumerate(transforms(p)):
        if len(t)==h and len(t[0])==w:
            err=sum(a!=b for row1,row2 in zip(actual,t) for a,b in zip(row1,row2))
            scores.append((err,i))
    print(name, min(scores) if scores else 'none', 'actual',actual[:4])

for name,grid,rs,cs,h,w in [('Bur',d10,0,7,4,3),('Blr',d10,5,7,5,3),('Aur',d20,0,8,5,12),('All',d20,6,0,14,7),('Alr',d20,6,8,14,12)]:
 act=[[int(grid[rs+r][cs+c]==4) for c in range(w)] for r in range(h)]
 candidates=[]
 for base in [P(h,w),P(w,h)]:
  for idx,t in enumerate(transforms(base)):
   if len(t)==h and len(t[0])==w:
    err=sum(x!=y for a,b in zip(act,t) for x,y in zip(a,b))
    candidates.append((err, 'normal' if base==P(h,w) else 'swap',idx,t))
 best=min(candidates,key=lambda x:x[0])
 print(name,best[:3],best[3])

for name,grid,rs,cs,h,w in [('Bul',d10,0,0,4,6),('Bll',d10,5,0,5,6),('Bur',d10,0,7,4,3),('Bll',d10,5,0,5,6),('Aul',d20,0,0,5,7),('Aur',d20,0,8,5,12),('All',d20,6,0,14,7),('Alr',d20,6,8,14,12)]:
